from pathlib import Path

import pytest


def _safe_target(path: str) -> Path | None:
    """Resolve `path` to a file under the directory `notes` (relative to the
    working directory). Return None when the name would leave `notes`,
    including via absolute paths, `..` segments, or symlinks that point
    outside it. Paths that wander but stay inside (e.g. `sub/../a.txt`)
    resolve normally.
    """
    try:
        base = (Path.cwd() / "notes").resolve()
        target = (base / path).resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if not target.is_relative_to(base):
        return None
    return target


def read_public(path: str) -> str:
    """Return the text of the file `notes/<path>`.

    Returns "" when the name escapes `notes`, or when the file is missing,
    is not a regular file, or cannot be read. Never reads outside `notes`.
    """
    target = _safe_target(path)
    if target is None:
        return ""
    try:
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError, ValueError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    return tmp_path


def test_reads_file_in_notes(workdir: Path) -> None:
    assert read_public("a.txt") == "hello"


def test_reads_nested_file(workdir: Path) -> None:
    assert read_public("sub/b.txt") == "nested"


def test_wandering_path_that_stays_inside_is_allowed(workdir: Path) -> None:
    assert read_public("sub/../a.txt") == "hello"


def test_missing_file_gives_empty(workdir: Path) -> None:
    assert read_public("nope.txt") == ""


def test_directory_gives_empty(workdir: Path) -> None:
    assert read_public("sub") == ""


def test_parent_escape_gives_empty(workdir: Path) -> None:
    assert read_public("../secret.txt") == ""


def test_deep_escape_gives_empty(workdir: Path) -> None:
    assert read_public("sub/../../secret.txt") == ""


def test_bare_parent_gives_empty(workdir: Path) -> None:
    assert read_public("..") == ""


def test_absolute_path_outside_notes_gives_empty(workdir: Path) -> None:
    assert read_public(str(workdir / "secret.txt")) == ""


def test_symlink_pointing_outside_gives_empty(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported here")
    assert read_public("link.txt") == ""
